\documentclass{article}
\usepackage{pgfplots}
\usepackage{tkz-euclide}
\usepackage{tikz}
\usetkzobj{all}
\usetikzlibrary{arrows}
\usetikzlibrary{arrows,decorations.markings} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

\begin{axis}[
	tick label style={font=\footnotesize},
	label style={font=\small},
	tick style={draw=black, thick},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	%grid = both,
	xmin = -1,
	xmax = 6,
	ymin = -2,
	ymax = 5,
	xtick = {1,2,3,4}, minor xtick={}, % xticklabels = {$\frac{\pi}{2}$},
	ytick = {0,1,2,3}, minor ytick={}, % yticklabels = {$\frac{\pi}{2}$},   	
	%% Here, we can control the positioning of each individual tick.
	%x tick label style={xshift={(\tick==3)*-5pt}},
	%x tick label style={xshift={(\tick==9)*5pt}},
	%y tick label style={yshift={(\tick==3)*-5pt}},
	%y tick label style={yshift={(\tick==9)*5pt}},
	xlabel = {$x$}, ylabel = {$y$},
	xlabel style={right}, ylabel style={above},
	]

% Rectangle boundaries
\def\xmin{-10}
\def\xmax{5}
\def\ymin{-10}
\def\ymax{4}

\draw[thin, dashed, opacity=0.3] (axis cs:0,\ymin) -- (axis cs:\xmin,\ymin);
\draw[thin, dashed, opacity=0.3] (axis cs:0,\ymax) -- (axis cs:\xmin,\ymax);	
\draw[thin, dashed, opacity=0.3] (axis cs:\xmin,0) -- (axis cs:\xmin,\ymin);
\draw[thin, dashed, opacity=0.3] (axis cs:\xmax,0) -- (axis cs:\xmax,\ymin);

% Rectangle
\draw [draw=none, fill=deepskyblue!50, fill opacity=0.3] (axis cs:\xmin,\ymin) rectangle (axis cs:\xmax,\ymax);
\draw [color=deepskyblue, very thick] (axis cs:\xmin,\ymax) -- (axis cs:\xmax,\ymax) -- (axis cs:\xmax,\ymin);	
\draw [color=deepskyblue, very thick, dashed] (axis cs:\xmin,\ymax) -- (axis cs:\xmin,\ymin) -- (axis cs:\xmax,\ymin);

% Lattice points
\pgfplotsinvokeforeach{0,1,2,3}{	% Y Support
	\foreach \xValue in {1,2,3,4}{	% X Support
	    \edef\temp{
    	\noexpand\node[circle, draw=none, fill=black, inner sep=1.4pt] at (axis cs: \xValue,#1) {};
 	   }
   	 \temp
}}

% top-right of rectangle
\node[
    circle,
    draw=none,
    fill=orangepeel,
    inner sep=1.5pt,
    label={[above right=-2pt, xshift=-2pt]:\small $(x, y)$}
] at (axis cs:\xmax,\ymax) {};
\node[] at (axis cs: -0.5,-0.5) {$\Delta$};

\end{axis}

\end{tikzpicture}
\end{document}
